CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, secret TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY, name TEXT NOT NULL, redirects TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pending (id TEXT PRIMARY KEY, data TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS codes (hash TEXT PRIMARY KEY, client TEXT NOT NULL, account TEXT NOT NULL, redirect TEXT NOT NULL, challenge TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens (hash TEXT PRIMARY KEY, kind TEXT NOT NULL, client TEXT NOT NULL, account TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS tokens_account ON tokens(account);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, account TEXT NOT NULL, name TEXT NOT NULL, running INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS agents_account ON agents(account);
CREATE INDEX IF NOT EXISTS agents_running ON agents(running);
CREATE TABLE IF NOT EXISTS proposals (id TEXT PRIMARY KEY, account TEXT NOT NULL, agent TEXT, rule TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cb_candles (product TEXT NOT NULL, t INTEGER NOT NULL, o REAL NOT NULL, h REAL NOT NULL, l REAL NOT NULL, c REAL NOT NULL, v REAL NOT NULL, PRIMARY KEY (product, t));
CREATE TABLE IF NOT EXISTS cb_state (product TEXT PRIMARY KEY, next INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cb_err (product TEXT PRIMARY KEY, at INTEGER NOT NULL, msg TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents_v2 (id TEXT PRIMARY KEY, account TEXT NOT NULL, name TEXT NOT NULL, running INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL, ver INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS agents_v2_account ON agents_v2(account);
CREATE INDEX IF NOT EXISTS agents_v2_running ON agents_v2(running);
